// 1. Capturar las respuestas que envió el formulario web
const respuestas = $('Webhook').item.json.body.respuestas || [];
const usuarioEmail = $('Webhook').item.json.body.email || "anonimo@ethosandgrowth.com";

// 2. Crear las cajas para contar los puntos de los 3 gráficos DISC
let graficoPublico = { D: 0, I: 0, S: 0, C: 0 };
let graficoPrivado = { D: 0, I: 0, S: 0, C: 0 };
let graficoSintesis = { D: 0, I: 0, S: 0, C: 0 };

// 3. Contar matemáticamente los votos del test
respuestas.forEach(voto => {
  if (voto.mas && graficoPublico.hasOwnProperty(voto.mas)) {
    graficoPublico[voto.mas] += 1;
  }
  if (voto.menos && graficoPrivado.hasOwnProperty(voto.menos)) {
    graficoPrivado[voto.menos] += 1;
  }
});

// 4. Calcular el Perfil Síntesis (MÁS menos MENOS)
for (let factor in graficoSintesis) {
  graficoSintesis[factor] = graficoPublico[factor] - graficoPrivado[factor];
}

// 5. Determinar la combinación de perfil dominante
let factoresOrdenados = Object.keys(graficoSintesis).sort((a, b) => graficoSintesis[b] - graficoSintesis[a]);
let factorPrincipal = factoresOrdenados[0];
let factorSecundario = factoresOrdenados[1];

let nombrePerfil = "Evaluación Equilibrada";
if (graficoSintesis[factorPrincipal] > 0) {
  if (factorPrincipal === 'D' && factorSecundario === 'I') nombrePerfil = "Persuasivo / Motivador";
  else if (factorPrincipal === 'D' && factorSecundario === 'C') nombrePerfil = "Director / Desarrollador";
  else if (factorPrincipal === 'I' && factorSecundario === 'S') nombrePerfil = "Relacionista / Consejero";
  else if (factorPrincipal === 'C' && factorSecundario === 'S') nombrePerfil = "Especialista / Técnico";
  else if (factorPrincipal === 'D') nombrePerfil = "Ejecutor / Conductor Puro";
  else if (factorPrincipal === 'I') nombrePerfil = "Influenciador Puro";
  else if (factorPrincipal === 'S') nombrePerfil = "Estable / Soporte Puro";
  else if (factorPrincipal === 'C') nombrePerfil = "Analítico / Cumplidor Puro";
}

// 6. Devolver los datos limpios y organizados
return [
  {
    json: {
      email: usuarioEmail,
      perfilAsignado: nombrePerfil,
      graficos: {
        publico_mas: graficoPublico,
        privado_menos: graficoPrivado,
        sintesis_total: graficoSintesis
      },
      metadatos: {
        totalBloquesRespondidos: respuestas.length,
        fechaProcesado: new Date().toISOString()
      }
    }
  }
];
